mapper.update:
UPDATE crm_reply_template SET name = #{name}, category = #{category}, content = #{content},
       language = #{language}, enabled = #{enabled}, updated_at = #{updatedAt}
WHERE template_id = #{templateId} AND tenant_id = #{tenantId}

mapper.select:
SELECT template_id, tenant_id, name, category, content, language, enabled, created_at, updated_at
FROM crm_reply_template WHERE tenant_id = #{tenantId}
AND category = #{category}
ORDER BY created_at DESC

mapper.update:
UPDATE crm_complaint SET status = #{status}, handler_id = #{handlerId}, resolution = #{resolution},
       resolved_at = #{resolvedAt}, updated_at = #{updatedAt}
WHERE complaint_id = #{complaintId} AND tenant_id = #{tenantId}

mapper.select:
SELECT complaint_id, tenant_id, customer_id, order_id, channel, type, severity, status,
       subject, description, handler_id, resolution, complained_at, resolved_at, created_at, updated_at
FROM crm_complaint WHERE tenant_id = #{tenantId} AND complaint_id = #{complaintId}

SELECT complaint_id, tenant_id, customer_id, order_id, channel, type, severity, status,
       subject, description, handler_id, resolution, complained_at, resolved_at, created_at, updated_at
FROM crm_complaint WHERE tenant_id = #{tenantId}
AND status = #{status}
ORDER BY complained_at DESC

SELECT tag_id, tenant_id, customer_id, tag_name, tag_value, tagged_at
FROM crm_customer_tag WHERE tenant_id = #{tenantId} AND customer_id = #{customerId}
ORDER BY tagged_at DESC

SELECT review_id, tenant_id, customer_id, product_id, order_id, platform, rating,
       title, text, sentiment, verified, responded, review_date, created_at, updated_at
FROM crm_review WHERE tenant_id = #{tenantId} AND review_id = #{reviewId}

SELECT message_id, tenant_id, platform, customer_id, subject, body, direction, assigned_to, status, message_date, created_at, updated_at
FROM crm_message WHERE tenant_id = #{tenantId} AND customer_id = #{customerId}
ORDER BY message_date DESC

SELECT profile_id, tenant_id, customer_id, segment, lifetime_value, avg_order_value,
       total_orders, total_returns, return_rate, preferred_channel, preferred_language,
       risk_level, attributes, first_order_at, last_order_at, created_at, updated_at
FROM crm_customer_profile WHERE tenant_id = #{tenantId}
AND segment = #{segment}
ORDER BY lifetime_value DESC

SELECT behavior_id, tenant_id, customer_id, behavior_type, channel, object_type, object_id, context, occurred_at, created_at
FROM crm_customer_behavior WHERE tenant_id = #{tenantId}
AND customer_id = #{customerId}
AND behavior_type = #{behaviorType}
ORDER BY occurred_at DESC
